# AI-GENERATED FILE: written by Claude (Anthropic), not hand-written by the developer.
"""Patcher: version mapping, patch file naming, cache validation and source detection.

The build tables (``patches/data.py``) only exist after a build, and ``patches/__init__.py``
falls back to empty tables without them, so the tests that need real build data skip rather than
fail on a fresh clone.

KR-014 is the reason ``patch_validate`` is exercised here: the cache used to trust a sidecar
hash file instead of the patched data itself.
"""

from __future__ import annotations

import hashlib
import tempfile
import unittest
from pathlib import Path

from ... import APWORLD_VERSION
from ...client.patcher import (
    APWorldVersionTooHighError,
    APWorldVersionTooLowError,
    _decompose_patch_name,
    _get_mod_version,
    _get_source_map,
    _hash_multiple_files,
    _make_patch_name,
    _patch_map_str,
    apworld_to_mod_map,
    max_apworld,
    min_apworld,
    patch_validate,
    source_get,
    source_validate,
    validate_version,
)
from ...patches import builds, patch_map
from ..support.sandbox import RedirectedTestCase

HAS_BUILD_DATA = bool(builds) and bool(patch_map)
BUILD_DATA_REASON = "patches/data.py is generated by the build; a fresh clone has empty tables"


class TestVersionMapping(unittest.TestCase):
    """``_get_mod_version`` decides which mod release a host's apworld can be played with."""

    def test_the_current_version_maps_to_a_mod_release(self) -> None:
        self.assertEqual(
            _get_mod_version(APWORLD_VERSION),
            apworld_to_mod_map[max_apworld],
            f"the running apworld version {APWORLD_VERSION} does not map to the newest mod release"
        )

    def test_a_newer_host_is_refused(self) -> None:
        # The host generated with an apworld this client has never heard of.
        with self.assertRaises(APWorldVersionTooHighError):
            _get_mod_version("99.0.0")

    def test_an_older_host_is_refused(self) -> None:
        lower = (min_apworld[0], min_apworld[1], min_apworld[2] - 1)
        with self.assertRaises(APWorldVersionTooLowError):
            _get_mod_version(".".join(str(part) for part in lower))

    def test_malformed_versions_are_refused(self) -> None:
        for version in ("1.0", "1.0.0.0", "a.b.c", ""):
            with self.subTest(version=version):
                with self.assertRaises(ValueError):
                    _get_mod_version(version)

    def test_validate_version_is_the_same_check(self) -> None:
        validate_version(APWORLD_VERSION)
        with self.assertRaises(ValueError):
            validate_version("nope")

    @unittest.skipUnless(HAS_BUILD_DATA, BUILD_DATA_REASON)
    def test_the_mapped_release_has_builds(self) -> None:
        mod_version = _get_mod_version(APWORLD_VERSION)
        source_map = _get_source_map(mod_version)
        self.assertTrue(
            source_map,
            f"mod release {mod_version} has no supported game builds, so no source can ever be loaded"
        )
        for build_hash, build_name in source_map.items():
            self.assertRegex(build_hash, r"^[0-9a-f]{32}$", f"build \"{build_name}\" has a malformed hash")


class TestPatchNaming(unittest.TestCase):
    """Patch files are named ``<mod version>_<build>.win`` and parsed back out of that."""

    def test_round_trip_from_a_version_tuple(self) -> None:
        name = _make_patch_name("itch-v4.2", (0, 1, 0))
        self.assertEqual(name, "0.1.0_itch-v4.2.win")
        self.assertEqual(_decompose_patch_name(name), ("0.1.0", "itch-v4.2"))

    def test_round_trip_from_a_version_string(self) -> None:
        self.assertEqual(_make_patch_name("steam-v4.2", "0.1.0"), "0.1.0_steam-v4.2.win")

    def test_build_names_may_contain_underscores(self) -> None:
        # Only the first underscore separates the version, so the build name keeps the rest.
        self.assertEqual(_decompose_patch_name("0.1.0_build_with_parts.win"), ("0.1.0", "build_with_parts"))

    def test_malformed_names_are_refused(self) -> None:
        for name in ("0.1.0.win", "no-extension", "0.1.0_build.txt", "", "0.1.0_build.win.bak"):
            with self.subTest(name=name):
                with self.assertRaises(ValueError):
                    _decompose_patch_name(name)


class TestFolderHashing(unittest.TestCase):
    """``_hash_multiple_files`` has to match the mod's own ``make_meta.py``."""

    def setUp(self) -> None:
        self.root = Path(self.enterContext(tempfile.TemporaryDirectory(ignore_cleanup_errors=True)))
        self.first = self.root / "a.txt"
        self.second = self.root / "b.txt"
        self.first.write_bytes(b"first")
        self.second.write_bytes(b"second")

    def test_order_does_not_matter(self) -> None:
        self.assertEqual(
            _hash_multiple_files([self.first, self.second]),
            _hash_multiple_files([self.second, self.first]),
            "the hash depends on the order the files are listed in, so it cannot be compared across machines"
        )

    def test_content_matters(self) -> None:
        before = _hash_multiple_files([self.first, self.second])
        self.second.write_bytes(b"changed")
        self.assertNotEqual(before, _hash_multiple_files([self.first, self.second]))

    def test_names_matter(self) -> None:
        before = _hash_multiple_files([self.first, self.second])
        renamed = self.root / "c.txt"
        self.second.rename(renamed)
        self.assertNotEqual(
            before,
            _hash_multiple_files([self.first, renamed]),
            "renaming a file left the hash unchanged, so a swapped file would go unnoticed"
        )

    def test_missing_files_are_skipped(self) -> None:
        self.assertEqual(
            _hash_multiple_files([self.first, self.root / "gone.txt"]),
            _hash_multiple_files([self.first])
        )

    def test_directories_are_skipped(self) -> None:
        (self.root / "subfolder").mkdir()
        self.assertEqual(
            _hash_multiple_files([self.first, self.root / "subfolder"]),
            _hash_multiple_files([self.first])
        )


class TestPatchValidation(RedirectedTestCase):
    """KR-014: a cached patch is only accepted after its own bytes are checked."""

    def test_a_missing_file_is_invalid(self) -> None:
        self.assertFalse(patch_validate(self.user_root / "nothing.win"))

    def test_a_malformed_name_is_invalid(self) -> None:
        path = self.user_root / "not-a-patch.win"
        path.write_bytes(b"content")
        self.assertFalse(patch_validate(path))

    def test_an_unknown_build_is_invalid(self) -> None:
        path = self.user_root / "0.1.0_not-a-build.win"
        path.write_bytes(b"content")
        self.assertFalse(patch_validate(path))

    @unittest.skipUnless(HAS_BUILD_DATA, BUILD_DATA_REASON)
    def test_wrong_content_is_invalid(self) -> None:
        # A patch of the right name but the wrong bytes is exactly the corrupted-cache case.
        (version, build), expected = next(iter(_patch_map_str.items()))
        path = self.user_root / _make_patch_name(build, version)
        path.write_bytes(b"\x00" * expected.size)
        self.assertEqual(path.stat().st_size, expected.size, "the decoy should match on size alone")
        self.assertNotEqual(
            hashlib.md5(path.read_bytes()).hexdigest(),
            expected.hash_id,
            "the decoy accidentally matches the real hash"
        )
        self.assertFalse(
            patch_validate(path),
            "a patch with the right name and size but the wrong content was accepted"
        )

    @unittest.skipUnless(HAS_BUILD_DATA, BUILD_DATA_REASON)
    def test_wrong_size_is_invalid(self) -> None:
        (version, build), _expected = next(iter(_patch_map_str.items()))
        path = self.user_root / _make_patch_name(build, version)
        path.write_bytes(b"too short")
        self.assertFalse(patch_validate(path))


class TestSourceDetection(RedirectedTestCase):
    """``source_validate`` and ``source_get`` decide whether a usable game build is stored."""

    def test_a_missing_folder_is_not_a_build(self) -> None:
        self.assertEqual(source_validate(self.user_root / "nothing"), (False, None))

    def test_a_folder_without_game_data_is_not_a_build(self) -> None:
        folder = self.user_root / "empty_build"
        folder.mkdir()
        self.assertEqual(source_validate(folder), (False, None))

    def test_an_unknown_game_data_file_is_not_a_build(self) -> None:
        folder = self.user_root / "wrong_build"
        folder.mkdir()
        (folder / "data.win").write_bytes(b"not the game")
        self.assertEqual(
            source_validate(folder),
            (False, None),
            "an unrecognised data.win was accepted as a supported build"
        )

    def test_no_stored_sources_means_no_sources(self) -> None:
        # Storage is redirected to an empty temporary folder, so nothing can be found.
        self.assertEqual(source_get(APWORLD_VERSION), [])
